def transform(g):
    h, w = len(g), len(g[0])
    out = [row[:] for row in g]
    for c in range(w):
        seeds = [(r, g[r][c]) for r in range(h) if g[r][c]]
        if not any(r == h - 1 and v == 5 for r, v in seeds):
            continue
        for r in range(h):
            _, value = min(seeds, key=lambda s: (abs(s[0] - r), -s[0]))
            out[r][c] = value
    return out
